import type { ReactNode } from "react";
import WorkspaceSidebar from "./WorkspaceSidebar";

export type PrimaryView = "chat" | "quests" | "memory";

export interface DesktopNavigationProps {
  compact: boolean;
  activeView: PrimaryView | null;
  connected: boolean;
  workspaceId: string;
  workspaceRoot: string;
  onNavigate: (view: PrimaryView) => void;
  onSettings: () => void;
  children: ReactNode;
}

function NavigationIcon({ view }: { view: PrimaryView }) {
  return <svg className="nav-icon" viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
    {view === "chat" ? <><path d="M5 4h14a2 2 0 0 1 2 2v10a2 2 0 0 1-2 2H9l-6 3V6a2 2 0 0 1 2-2Z" /><path d="M7 9h10M7 13h6" /></>
      : view === "quests" ? <><circle cx="12" cy="12" r="8.5" /><path d="M12 7v5l3.5 2" /></>
        : <><path d="M12 3.5 20.5 12 12 20.5 3.5 12Z" /><circle cx="12" cy="12" r="2.5" /></>}
  </svg>;
}

/** Keep every destination mounted once while its layout changes with the workspace panel. */
export default function DesktopNavigation({
  compact, activeView, connected, workspaceId, workspaceRoot, onNavigate, onSettings, children,
}: DesktopNavigationProps) {
  return <aside className={`rail${compact ? " rail-compact" : ""}`} aria-label="主导航">
    <div className="primary-rail">
      <div className="rail-brand" aria-hidden="true">
        <svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"><path d="m12 3 8 4.5v9L12 21l-8-4.5v-9L12 3Z" /><path d="m8 15 4-7 4 7M10 12h4" /></svg>
      </div>
      <nav className="utility-nav">
        {([{ view: "quests", name: "后台任务", label: "任务" }, { view: "memory", name: "记忆中心", label: "记忆" }] as const).map((item) => <button
          key={item.view}
          type="button"
          className={`nav-item utility-nav-item${activeView === item.view ? " active" : ""}`}
          data-view={item.view}
          data-tooltip={item.label}
          aria-label={item.name}
          aria-current={activeView === item.view ? "page" : undefined}
          title={item.name}
          onClick={() => onNavigate(item.view)}
        ><NavigationIcon view={item.view} /></button>)}
      </nav>
      <button type="button" className="profile-button" aria-label="设置" title="设置 (Ctrl+,)" onClick={onSettings}>
        <span className="profile-avatar" aria-hidden="true">F</span>
      </button>
    </div>
    <WorkspaceSidebar
      connected={connected}
      workspaceId={workspaceId}
      workspaceRoot={workspaceRoot}
      active={!compact}
      navigation={<nav className="conversation-nav"><button
        type="button"
        className={`nav-item conversation-entry${activeView === "chat" ? " active" : ""}`}
        data-view="chat"
        data-tooltip="对话"
        aria-label="对话"
        aria-current={activeView === "chat" ? "page" : undefined}
        title="对话"
        onClick={() => onNavigate("chat")}
      ><NavigationIcon view="chat" /><span className="nav-label">对话</span></button></nav>}
    >{children}</WorkspaceSidebar>
  </aside>;
}

import { useCallback, useEffect, useRef, useState, type ReactNode } from "react";
import DisclosurePopover from "./DisclosurePopover";

export default function ConversationToolbar({ home, visible, status, sessionTitle, children }: {
  home: boolean; visible: boolean; status: string; sessionTitle?: string; children: ReactNode;
}) {
  const [open, setOpen] = useState(false);
  const trigger = useRef<HTMLButtonElement>(null);
  const close = useCallback(() => setOpen(false), []);
  useEffect(() => { if (!visible) setOpen(false); }, [visible]);
  return <header className="topbar conversation-topbar" hidden={home}>
    <div className="topbar-title" title={sessionTitle}><h1>长期对话</h1></div>
    <div className="conversation-status">
      <span className="router-status" title={status}><span className="status-dot" />Router</span>
      <div className="worker-menu-anchor">
        <button ref={trigger} type="button" className="worker-toggle" aria-label="查看 Worker 执行" aria-expanded={open} aria-controls="conversation-workers" onClick={() => setOpen((value) => !value)}>Worker<svg data-chevron viewBox="0 0 16 16" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.5" aria-hidden="true"><path d="m6 4 4 4-4 4" /></svg></button>
        <DisclosurePopover open={open && visible} onClose={close} trigger={trigger} id="conversation-workers" label="Worker 执行详情" className="worker-drawer">{children}</DisclosurePopover>
      </div>
    </div>
  </header>;
}

import { useCallback, useEffect, useRef, useState, type KeyboardEvent, type RefObject } from "react";
import DisclosurePopover from "./DisclosurePopover";

export default function ConversationComposer({ inputRef, value, onChange, onKeyDown, onSend, onConfigure, disabled, sending, workspace, workspaceName, native, model, provider, status, visible, error, requestId }: {
  inputRef: RefObject<HTMLTextAreaElement>; value: string; onChange: (value: string) => void;
  onKeyDown: (event: KeyboardEvent<HTMLTextAreaElement>) => void; onSend: () => void;
  onConfigure: (setting: "environment" | "models") => void;
  disabled: boolean; sending: boolean; workspace: string; workspaceName: string; native: boolean;
  model: string; provider: string; status: string; visible: boolean; error: string; requestId?: string;
}) {
  const [open, setOpen] = useState(false);
  const trigger = useRef<HTMLButtonElement>(null);
  const close = useCallback(() => setOpen(false), []);
  useEffect(() => { if (!visible) setOpen(false); }, [visible]);
  const configure = (setting: "environment" | "models") => { setOpen(false); onConfigure(setting); };
  return <footer className="composer-wrap"><div className="composer-stack">
    <div className="composer-context">
      <span title={workspace}><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><path d="M3 7h7l2 2h9v10H3V7Zm0 0V5h7l2 2" /></svg><span className="composer-workspace-name">{workspaceName}</span></span>
      <span><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><rect x="4" y="4" width="16" height="12" rx="1.5" /><path d="M2 20h20M9 16v4m6-4v4" /></svg>{native ? "本地" : "开发连接"}</span>
    </div>
    <div className="composer">
      <textarea ref={inputRef} value={value} onChange={(event) => onChange(event.target.value)} onKeyDown={onKeyDown} placeholder="给 Router 发送消息…" aria-label="消息内容" />
      <div className="composer-bottom">
        <span className="composer-router" title={status}><svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><path d="m12 3 7.5 4.5v9L12 21l-7.5-4.5v-9L12 3Z" /><path d="m4.5 7.5 7.5 5 7.5-5M12 12.5V21" /></svg>Router</span>
        <span className="composer-keyboard sr-only">Enter 发送 · Shift + Enter 换行</span>
        <div className="composer-model-anchor">
          <button ref={trigger} type="button" className="composer-model" aria-label="查看 Router 配置" aria-expanded={open} aria-controls="router-model-configuration" title={[provider, model].filter(Boolean).join(" / ")} onClick={() => setOpen((value) => !value)}><span>{model}</span><svg viewBox="0 0 16 16" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.5" aria-hidden="true"><path d="m5 6 3 3 3-3" /></svg></button>
          <DisclosurePopover open={open && visible} onClose={close} trigger={trigger} id="router-model-configuration" label="Router 模型配置" className="composer-model-menu">
            <div className="model-menu-current"><span className="model-menu-label">当前 Router</span><strong className="router-model">{model}</strong><span className="router-provider">{provider || "供应商未记录"}</span></div>
            <div className="model-menu-actions"><button type="button" aria-label="环境" onClick={() => configure("environment")}>运行配置<svg viewBox="0 0 16 16" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.5" aria-hidden="true"><path d="m6 4 4 4-4 4" /></svg></button><button type="button" onClick={() => configure("models")}>模型库<svg viewBox="0 0 16 16" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.5" aria-hidden="true"><path d="m6 4 4 4-4 4" /></svg></button></div>
          </DisclosurePopover>
        </div>
        <button className="send-button" aria-label="发送消息" disabled={disabled} onClick={onSend}>{sending ? <span className="loading-spinner" aria-hidden="true" /> : <svg viewBox="0 0 20 20" width="18" height="18" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><path d="M10 16V4m-5 5 5-5 5 5" /></svg>}</button>
      </div>
    </div>
  </div>{error && <p className="send-error" role="alert">{error} 草稿已保留。请求 ID：<code>{requestId}</code></p>}</footer>;
}

import { useEffect, useLayoutEffect, useRef, type ReactNode, type RefObject } from "react";

/** A measured disclosure that stays mounted through polling and dismissal. */
export default function DisclosurePopover({ open, onClose, trigger, id, label, className, children }: {
  open: boolean; onClose: () => void; trigger: RefObject<HTMLButtonElement>;
  id: string; label: string; className: string; children: ReactNode;
}) {
  const panel = useRef<HTMLDivElement>(null);
  useLayoutEffect(() => {
    const element = panel.current;
    if (!element) return;
    element.toggleAttribute("inert", !open);
    const finish = () => { element.style.height = open ? "auto" : "0px"; element.style.opacity = open ? "1" : "0"; };
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) { finish(); return; }
    element.style.height = `${element.getBoundingClientRect().height}px`;
    void element.offsetHeight;
    let timeout = 0;
    const frame = requestAnimationFrame(() => {
      element.style.height = open ? `${element.scrollHeight}px` : "0px";
      element.style.opacity = open ? "1" : "0";
      timeout = window.setTimeout(finish, 200);
    });
    const transitioned = (event: TransitionEvent) => { if (event.target === element && event.propertyName === "height") finish(); };
    element.addEventListener("transitionend", transitioned);
    return () => { cancelAnimationFrame(frame); window.clearTimeout(timeout); element.removeEventListener("transitionend", transitioned); };
  }, [open]);
  useEffect(() => {
    if (!open) return;
    const dismiss = () => { onClose(); trigger.current?.focus(); };
    const pointer = (event: PointerEvent) => {
      if (event.target instanceof Node && !panel.current?.contains(event.target) && !trigger.current?.contains(event.target)) onClose();
    };
    const key = (event: KeyboardEvent) => { if (event.key === "Escape") { event.preventDefault(); dismiss(); } };
    document.addEventListener("pointerdown", pointer);
    document.addEventListener("keydown", key);
    return () => { document.removeEventListener("pointerdown", pointer); document.removeEventListener("keydown", key); };
  }, [open, onClose, trigger]);
  return <div ref={panel} id={id} className={`disclosure-popover ${className}`} role="dialog" aria-label={label} aria-hidden={!open}>
    <div className="popover-surface">{children}</div>
  </div>;
}

